import{_ as d,c as t,o,b0 as c}from"./chunks/framework.BWMBvyU7.js";const a="data:image/png;base64,",s="data:image/png;base64,",i="/programming-docs/assets/image-20220613115855020.DbHBxZQh.png",n="/programming-docs/assets/4.Bp7GCvHH.gif",l="/programming-docs/assets/image-20220613121230055.UhSE8uq4.png",r="/programming-docs/assets/5.C53GKBWc.gif",h="/programming-docs/assets/6.G2dxJbd6.png",p="/programming-docs/assets/7.3EEzQHm2.gif",g="data:image/png;base64,",A="/programming-docs/assets/image-20220613141546642.2OjWOZYG.png",b="/programming-docs/assets/image-20220613144536471.BLfdW0wP.png",k="/programming-docs/assets/image-20220613145724335.CA47aevx.png",u="/programming-docs/assets/image-20220613150211229.BHR7-fRb.png",m="/programming-docs/assets/image-20220613150922494.B_XdrOaI.png",C="/programming-docs/assets/image-20220613154045980.BGDKZSmI.png",F="/programming-docs/assets/image-20220613162405651.KFmc0FjO.png",P="/programming-docs/assets/10.CQeegr04.gif",y="/programming-docs/assets/11.Lv_CnpoK.png",f="/programming-docs/assets/12.KYSk97ig.gif",v="/programming-docs/assets/image-20220613202143988.DyqNf6aa.png",E="/programming-docs/assets/image-20220613202749784.CgDwgoWU.png",M="/programming-docs/assets/image-20220613203221165.4S79vPAL.png",x="/programming-docs/assets/image-20220614053923911.aO2t-muX.png",T=JSON.parse('{"title":"LV005-网络中的各种设备","description":null,"frontmatter":{"title":"LV005-网络中的各种设备","date":"2026-03-16T14:16:32.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/net/net-basic/126d38f258401a045a85a088","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-03-16T14:16:32.416Z","fulluuid":"45a85a088e684064a86edef302ebc5e2","useduuid":"45a85a088"}},"headers":[],"relativePath":"sdoc/net/net-basic/126d38f258401a045a85a088.md","filePath":"sdoc/04-网络相关/10-网络基础/LV005-网络中的各种设备.md","lastUpdated":1773672539000}'),B={name:"sdoc/net/net-basic/126d38f258401a045a85a088.md"};function q(w,e,I,z,S,L){return o(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="lv005-网络中的各种设备" tabindex="-1">LV005-网络中的各种设备 <a class="header-anchor" href="#lv005-网络中的各种设备" aria-label="Permalink to &quot;LV005-网络中的各种设备&quot;">​</a></h1><p>本文主要是网络基础——网络中的各种设备以及网络是怎么实现数据传输的基础知识的相关笔记，若笔记中有错误或者不合适的地方，欢迎批评指正😃。</p><h2 id="一、网线" tabindex="-1">一、网线 <a class="header-anchor" href="#一、网线" aria-label="Permalink to &quot;一、网线&quot;">​</a></h2><h3 id="_1-两台计算机" tabindex="-1">1. 两台计算机 <a class="header-anchor" href="#_1-两台计算机" aria-label="Permalink to &quot;1. 两台计算机&quot;">​</a></h3><p>我们现在有两台电脑，如何完成它们之间的通信？它们都有网口，我们只需要一根网线就可以了，就像下边这样：</p><img src="'+a+'" alt="img"><p>我们知道数据在计算机中是以二进制的形式存储的，两台计算机通信时传输的当然也就是二进制数据啦。网线常用高低电平来分别表示 <code>0</code> 和 <code>1</code>，从而将二进制数据传输给对方。若上图的 <code>A</code> 向 <code>B</code> 发送数据，<code>A</code> 机器的网卡会将数据包转换成电信号，电信号通过网线就可以传送给 <code>B</code> 机器。<code>B</code> 机器的网卡接收到电信号后，会将其还原成二进制数据。</p><h3 id="_2-三台计算机" tabindex="-1">2. 三台计算机 <a class="header-anchor" href="#_2-三台计算机" aria-label="Permalink to &quot;2. 三台计算机&quot;">​</a></h3><p>突然发现，两台计算机不够用了，现在再买一台<code>C</code>计算机，这样这三台计算机依然可以通过网线连接，每个计算机有两个网口就可以啦。</p><img src="'+s+'" alt="img" style="zoom:80%;"><p>这样也还行，还可以接受。</p><h3 id="_3-五台计算机呢" tabindex="-1">3. 五台计算机呢？ <a class="header-anchor" href="#_3-五台计算机呢" aria-label="Permalink to &quot;3. 五台计算机呢？&quot;">​</a></h3><img src="'+i+'" alt="image-20220613115855020" style="zoom:50%;"><p>是不是就有些眼花了，要是更多的计算机怎么办？有这么多线，也没这么多网口啊。</p><h2 id="二、集线器" tabindex="-1">二、集线器 <a class="header-anchor" href="#二、集线器" aria-label="Permalink to &quot;二、集线器&quot;">​</a></h2><h3 id="_1-集线器的出现" tabindex="-1">1. 集线器的出现 <a class="header-anchor" href="#_1-集线器的出现" aria-label="Permalink to &quot;1. 集线器的出现&quot;">​</a></h3><p>为了解决上边的问题，需要找一个中间设备，将网线都插到这个设备上，由这个设备做转发，这样也可以是实现通信，这本质上和原来一样，只不过网口的数量和网线的数量减少了：</p><img src="'+n+'" alt="img" style="zoom:95%;"><p>所有计算机没有直接建立通信，而是全部连接到中间的这台设备上，称为<strong>集线器</strong>（简称 <code>Hub</code>）。它仅仅是将电信号<strong>转发到所有出口（广播）</strong>，不做任何处理，于是将它定性在了<strong>物理层</strong>。</p><h3 id="_2-mac地址" tabindex="-1">2. <code>MAC</code>地址 <a class="header-anchor" href="#_2-mac地址" aria-label="Permalink to &quot;2. `MAC`地址&quot;">​</a></h3><p>接收到数据包的集线器，会把数据包转发给网络中的其它计算机。可是，计算机怎么知道数据是发给自己的呢？这个时候就需要一个唯一的标识，就像我们的名字一样，叫我们的名字，我们自然就知道是叫自己的啦。这个标识就是**<code>MAC</code>地址**。MAC地址也叫物理地址、硬件地址，长度为 48 位，一般这样来表示：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">16</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">EA</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">3C</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">40</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>它是由网络设备制造商生产时烧录在网卡的EPROM（一种闪存芯片，通常可以通过程序擦写）。其中<strong>前 24 位（00-16-EA）代表网络硬件制造商的编号</strong>，后 24 位（AE-3C-40）是该厂家自己分配的，一般表示系列号。只要不更改自己的 MAC 地址，MAC 地址在世界是唯一的。形象地说，MAC地址就如同身份证上的身份证号码，具有唯一性。</p><p>计算机在出厂时，它自己的<code>MAC</code> 地址已经被写到网卡里面了，每台计算机的 <code>MAC</code> 地址都是不一样的。假设 <code>A</code> 机器的 <code>MAC</code> 地址为 <code>aa-aa-aa-aa-aa-aa-aa</code>，<code>B</code> 机器的 <code>MAC</code> 地址为 <code>bb-bb-bb-bb-bb-bb</code>。当 <code>A</code> 机器向 <code>B</code> 机器发送数据时，数据包中会同时附带 <code>A</code> 和 <code>B</code> 的 <code>MAC</code> 地址，如下图所示：</p><img src="'+l+'" alt="image-20220613121230055" style="zoom:50%;"><p>这样一来，当 <code>B</code> 机器接收到数据包后，根据头部的 <code>MAC</code> 信息就可以判定是发给自己的了，就会收下这个数据包，其他的计算机收到数据包后，根据头部的目标 <code>MAC</code> 地址信息，判断这个数据包并不是发给自己的，于是便<strong>丢弃</strong>。</p><img src="'+r+'" alt="img" style="zoom:95%;"><h3 id="_3-集线器的缺点" tabindex="-1">3. 集线器的缺点 <a class="header-anchor" href="#_3-集线器的缺点" aria-label="Permalink to &quot;3. 集线器的缺点&quot;">​</a></h3><p>其实集线器比起直接使用网线连接，已经方便了很多了，但是，它还是有着一些缺点：</p><ul><li>数据被大量转发，原本只发给一台计算机的数据，集线器会转发给网络内的所有计算机，这是很浪费网络资源的。并且这种情况下，如果有多台计算机同时向集线器发送数据包，数据的转发就会产生冲突（碰撞），严重时会导致数据传输失败。</li><li>数据安全无法保证，集线器只是负责将数据转发给所有机器，就相当于一个中转站，它不会对数据包有任何的检测，即便数据包中有病毒，它也不管，数据的安全性很难得到保证。</li></ul><h2 id="三、交换机" tabindex="-1">三、交换机 <a class="header-anchor" href="#三、交换机" aria-label="Permalink to &quot;三、交换机&quot;">​</a></h2><h3 id="_1-交换机的出现" tabindex="-1">1. 交换机的出现 <a class="header-anchor" href="#_1-交换机的出现" aria-label="Permalink to &quot;1. 交换机的出现&quot;">​</a></h3><p>我们会想，为什么一定要把数据发送给所有的计算机，难道就不能直接找到目标机器，我直接发给它不行吗？为了解决这个问题，就需要将数据<strong>只发给目标 MAC 地址指向的那台电脑</strong>，于是出现了<strong>交换机</strong>。</p><p>交换机拥有多个端口，每个端口都可以连接一台计算机。为了实现精准转发，交换机内部维护着一张<strong>表格</strong>，主要记录每台计算机的 <code>MAC</code> 地址以及它所连接在的网口号，这张表格通常称为 <strong>MAC 地址表</strong>。就像这样：</p><img src="'+h+'" alt="img" style="zoom:80%;"><p>假如说我们还是要发给 <code>B</code> 一个数据包，构造了图中的数据包从网口出去。到达交换机时，交换机内部通过自己维护的 <code>MAC</code> 地址表，发现目标计算机 <code>B</code> 的 <code>MAC</code> 地址 <code>bb-bb-bb-bb-bb-bb</code> 连接在网口 <code>1</code> 上，于是把数据从 <code>1</code> 号网口发给了 <code>B</code>。</p><p>虽然交换机只比集线器多了这一点点区别，但是就是因为这一点的区别，我们就可以它放在<strong>数据链路层</strong>了（后边会再学习）。</p><p>我们通过这样传输方式而组成的小范围的网络，叫就是我们常说的<strong>以太网</strong>。这种基于交换数据包方式构建小型网络的技术称为<strong>以太网技术</strong>。以太网其实是一种组建网络的技术，由技术构建的小型网络称为<strong>局域网</strong>（<code>LAN</code>）。</p><h3 id="_2-地址表的建立" tabindex="-1">2. 地址表的建立 <a class="header-anchor" href="#_2-地址表的建立" aria-label="Permalink to &quot;2. 地址表的建立&quot;">​</a></h3><p>一开始的时候，交换机并不知道这个网络中究竟有哪些主机，那这张表是如何被建立起来的呢？</p><img src="'+p+'" alt="img" style="zoom:80%;"><p>建立过程是这样的：</p><ul><li>（1）计算机 <code>A</code> 发送的数据包进入交换机后，交换机的 <code>MAC</code> 地址表中会记录下 <code>A</code> 的 <code>MAC</code> 地址和占用的网口号；</li><li>（2）由于<code>MAC</code> 地址表没有和 计算机<code>B</code> 相关的信息，交换机会像集线器那样将数据包转发给连接在交换机上除 <code>A</code> 外的所有计算机；</li><li>（3）计算机 <code>B</code> 收到数据包后，确认数据是 <code>A</code> 发给自己的，于是收下数据，并向 <code>A</code> 回传一份响应数据；</li><li>（4）响应数据包进入交换机后，交换机会记录下 <code>B</code> 的 <code>MAC</code> 地址和占用的网口号；</li><li>（5）通过查询 <code>MAC</code> 地址表，交换机会将响应数据包通过 <code>4</code> 号网口发送给 <code>A</code>。</li></ul><p>这样地址表中就有计算机<code>A</code>和<code>B</code>的<code>MAC</code>地址和它们连接的网口号啦，随着网络中计算机相互通信，交换机内部的<code>MAC</code>地址表最终会建立完整。</p><h3 id="_3-多个交换机" tabindex="-1">3. 多个交换机 <a class="header-anchor" href="#_3-多个交换机" aria-label="Permalink to &quot;3. 多个交换机&quot;">​</a></h3><p>一台交换机的网口数毕竟还是是有限，随着计算机数量的增加，很可能要用多台交换机才能为所有机器建立通信，如下图所示：</p><img src="'+g+'" alt="img" style="zoom:80%;"><p>按照上述的接线方式即可完成所有电脑的互联，所以交换机设计的这种规则，真的很巧妙。但是需要注意，图中那根红色的线，最终在 <code>MAC</code> 地址表中可不会仅仅只有一条记录，而是要把 <code>EFGH</code> 这四台机器与该网口（网口<code>6</code>）的映射全部记录在表中。最终，<strong>两个交换机将分别记录 A ~ H 所有机器的映射记录</strong>如下。</p><table><tbody><tr><td align="center" colspan="2">左侧的交换机</td><td align="center" colspan="2">右侧的交换机</td></tr><tr><td align="center">MAC地址</td><td align="center">网口号</td><td align="center">MAC地址</td><td align="center">网口号</td></tr><tr><td align="center">aa-aa-aa-aa-aa-aa </td><td align="center">1</td><td align="center" style="color:red;">aa-aa-aa-aa-aa-aa</td><td align="center" style="color:red;">1</td></tr><tr><td align="center">bb-bb-bb-bb-bb-bb </td><td align="center">2</td><td align="center" style="color:red;">bb-bb-bb-bb-bb-bb</td><td align="center" style="color:red;">1</td></tr><tr><td align="center">cc-cc-cc-cc-cc-cc </td><td align="center">3</td><td align="center" style="color:red;">cc-cc-cc-cc-cc-cc</td><td align="center" style="color:red;">1</td></tr><tr><td align="center">dd-dd-dd-dd-dd-dd </td><td align="center">4</td><td align="center" style="color:red;">dd-dd-dd-dd-dd-dd</td><td align="center" style="color:red;">1</td></tr><tr><td align="center" style="color:red;">gg-gg-gg-gg-gg-gg </td><td align="center" style="color:red;">6</td><td align="center">ee-ee-ee-ee-ee-ee</td><td align="center">2</td></tr><tr><td align="center" style="color:red;">hh-hh-hh-hh-hh-hh </td><td align="center" style="color:red;">6</td><td align="center">ff-ff-ff-ff-ff-ff</td><td align="center">3</td></tr><tr><td align="center" style="color:red;">ee-ee-ee-ee-ee-ee </td><td align="center" style="color:red;">6</td><td align="center">gg-gg-gg-gg-gg-gg</td><td align="center">4</td></tr><tr><td align="center" style="color:red;">ff-ff-ff-ff-ff-ff </td><td align="center" style="color:red;">6</td><td align="center">hh-hh-hh-hh-hh-hh</td><td align="center">6</td></tr></tbody></table> 这在只有 8 台电脑的时候还好，甚至在只有几百台电脑的时候，都还好，所以这种交换机的设计方式，已经足足支撑一阵子了。但很遗憾，很快，电脑的数量就发展到几千、几万、几十万。 <h3 id="_4-交换机的缺点" tabindex="-1">4. 交换机的缺点 <a class="header-anchor" href="#_4-交换机的缺点" aria-label="Permalink to &quot;4. 交换机的缺点&quot;">​</a></h3><p>随着时代的发展，计算机越来越多，交换机的劣势也越来越明显：</p><ul><li>（1）网络中的每台交换机都需要维护大量的 <code>MAC</code> 地址，多个交换机连接起来之后，地址表重复的也越来越多（主要是因为那根红色的线），每台交换机的<code>MAC</code>地址表也会越来越大；</li><li>（2）当网络中的计算机频繁通信时，很容易发生<strong>广播风暴</strong>，严重时会导致网络瘫痪。所谓广播风暴，指的是由于某些原因（网卡损坏、网络设备误用、网络病毒等）导致网络中存在大量无用的数据包，占用着大量的网络资源，正常的数据包也无法在网络中有效传送，网络设备也会因高负荷运转而受到影响。</li></ul><h2 id="四、路由器" tabindex="-1">四、路由器 <a class="header-anchor" href="#四、路由器" aria-label="Permalink to &quot;四、路由器&quot;">​</a></h2><h3 id="_1-路由器的出现" tabindex="-1">1. 路由器的出现 <a class="header-anchor" href="#_1-路由器的出现" aria-label="Permalink to &quot;1. 路由器的出现&quot;">​</a></h3><p>计算机数量不断增多，交换机已经不能满足这么多计算机互联的需求了，其实问题的根本在于连出去的那根红色的网线，也就是交换机之间连接的那根线，后面不知道有多少个设备不断地连接进来，从而使得地址表越来越大。</p><p>这时候就会想，可不可以让那根红色的网线，接入一个<strong>新的设备</strong>，这个设备就跟电脑一样有自己独立的 <code>MAC</code> 地址，而且同时还能帮忙把数据包做一次<strong>转发</strong>呢？</p><p>于是，出现了<strong>路由器</strong>，路由器也是一种包含多个网口、能转发数据的设备，和交换机不同的是，路由器的每个网口都有<strong>独立</strong>的 <code>MAC</code> 地址。且可以帮我们把数据包做一次转发**，<strong>它可以定义在</strong>网络层**（后边会再学习）。</p><img src="'+A+'" alt="image-20220613141546642" style="zoom:50%;"><p>现在交换机的 <code>MAC</code> 地址表中，只需要多出一条 <code>MAC</code> 地址 <code>ABAB</code> 或者<code>CDCD</code>与其占用的网口的映射关系，就可以成功把数据包转交给路由器了。也就是说对于跨交换机发送数据的情况，交换机 <code>1</code> 的 <code>MAC</code>地址表中只需要记录 &quot;路由器 <code>MAC</code> 地址 <code>ABAB</code> ~ <code>3</code>号网口&quot; 这条信息即可，而不需要记录 <code>C</code>、<code>D</code> 相关的信息。同样，交换机 <code>2</code> 也是如此。并且路由器可以缩小广播风暴的影响范围。比如交换机<code>1</code>所在的局域网发生广播风暴，不会影响交换机 <code>2</code> 所在的局域网。</p><p><strong>注意，路由器的每一个端口，都有独立的 MAC 地址</strong>。</p><h3 id="_2-ip地址的出现" tabindex="-1">2. <code>IP</code>地址的出现 <a class="header-anchor" href="#_2-ip地址的出现" aria-label="Permalink to &quot;2. `IP`地址的出现&quot;">​</a></h3><p>数据已经可以从计算机<code>A</code>或者<code>B</code>发送到路由器了，那怎么继续把数据包发送给 <code>C</code> 和 <code>D</code>的数据包统统先发送给路由器呢？假如电计算机<code>C</code> 和 <code>D</code> 的 <code>MAC</code> 地址拥有共同的前缀，比如分别是:</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 的</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MAC</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 地址：FF-FF-FF-FF-CC-CC</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 的</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MAC</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 地址：FF-FF-FF-FF-DD-DD</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>那我们是否可以说，将目标<code>MAC</code> 地址为 <code>FF-FF-FF-FF-</code>开头的，统统先发送给路由器？当然是不可以的啦。我们知道它是由网络设备制造商生产时烧录在网卡的<code>EPROM</code>（一种闪存芯片，通常可以通过程序擦写）中的，是写死的，无法改变的。例如，</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">00-16-EA-AE-3C-40</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>其中前 <code>24</code> 位（<code>00-16-EA</code>）代表网络硬件制造商的编号，后 <code>24</code> 位（<code>AE-3C-40</code>）是该厂家自己分配的，一般表示系列号。只要不更改自己的 <code>MAC</code> 地址，<code>MAC</code> 地址<strong>在世界是唯一的</strong>。也就是说计算机的<code>MAC</code>地址就如同我们的身份证上的身份证号码一样，具有唯一性。</p><p>那如果我们希望向上面那样表示将目标 <code>MAC</code> 地址为 <code>FF-FF-FF-FF-</code>开头的，统一从路由器出去发给某一群设备（后面会提到这其实是子网的概念），那我们就需要要求某一子网下的计算机统统是购买同一个厂商制造的设备，还需要要求厂商在生产设备烧录 <code>MAC</code> 地址时，提前按照我们规划好的子网结构来定 <code>MAC</code> 地址，并且以后这个网络的结构都不能轻易改变。这，，，显然不可能嘛，这成本也太高了，而且万一有问题，换都换不了。</p><p>那怎么办呢？不能有一种新的地址，来解决上边的问题嘛？当然可以，这就是<code>IP</code>地址啦。可以给每一台机器一个 <code>32</code> 位的编号，如：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">11000000101010000000000000000001</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>有木有觉得这串数字太乱了，一点都不清楚，那我们就每<code>8</code>位点一个点：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">11000000.10101000.00000000.00000001</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>似乎还是不符合我们平时的习惯，我们再转化成十进制：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">192.168.0.1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这下就人性化多了嘛。最后我们可以给这个地址一个响亮的名字，<strong>IP 地址</strong>。现在局域网中的每一台计算机，既有自己的 <code>MAC</code> 地址，又有自己的 <code>IP</code> 地址；路由器的每个网口也是既有唯一的<code>MAC</code>地址，也有唯一的<code>IP</code>地址。 <code>IP</code> 地址是软件层面上的，可以随时修改，<code>MAC</code> 地址一般是无法修改的。</p><img src="'+b+'" alt="image-20220613144536471" style="zoom:50%;"><p>这样一个可以随时修改的 IP 地址，就可以根据我们规划的网络拓扑结构，来调整了。如上图所示，假如我想要发送数据包给 ABCD 其中一台设备，不论哪一台，我都可以这样描述，<strong>&quot;将 IP 地址为 192.168.0 开头的全部发送给到路由器，之后再怎么转发，交给它！&quot;</strong>。那交给路由器之后，路由器又是怎么把数据包准确转发给指定设备的呢？我们后面继续看。</p><h3 id="_3-重新组网后数据格式" tabindex="-1">3. 重新组网后数据格式 <a class="header-anchor" href="#_3-重新组网后数据格式" aria-label="Permalink to &quot;3. 重新组网后数据格式&quot;">​</a></h3><p>我们先给上面的组网方式中的每一台设备，加上自己的 <code>IP</code> 地址:</p><img src="'+k+'" alt="image-20220613145724335" style="zoom:50%;"><p>路由器的存在，使得交换机的 <code>MAC</code> 地址表中不再需要记录网络中所有机器的信息，例如图中的交换机 <code>1</code> 就不需要记录 <code>C</code>、<code>D</code> 的信息。在这样的网络中传输数据，数据包中除了要携带 <code>MAC</code> 地址，还要携带 <code>IP</code> 地址。</p><h4 id="_3-1-不跨路由传输" tabindex="-1">3.1 不跨路由传输 <a class="header-anchor" href="#_3-1-不跨路由传输" aria-label="Permalink to &quot;3.1 不跨路由传输&quot;">​</a></h4><p>假如 <code>A</code> 给 <code>B</code> 发送数据，由于它们直接连着交换机，所以 <code>A</code> 直接发出如下数据包即可，这个时候网络层还没有体现出作用。</p><img src="'+u+'" alt="image-20220613150211229" style="zoom:50%;"><h4 id="_3-2-跨路由传输" tabindex="-1">3.2 跨路由传输 <a class="header-anchor" href="#_3-2-跨路由传输" aria-label="Permalink to &quot;3.2 跨路由传输&quot;">​</a></h4><p>现在要是想从<code>A</code>发送数据到<code>C</code>，<code>A</code> 就需要先转交给路由器，然后再由路由器转交给 <code>C</code>。由于最底层的传输仍然需要依赖以太网，所以数据包是分成两段的。</p><img src="'+m+`" alt="image-20220613150922494" style="zoom:50%;"><h3 id="_4-几个问题的解决" tabindex="-1">4. 几个问题的解决 <a class="header-anchor" href="#_4-几个问题的解决" aria-label="Permalink to &quot;4. 几个问题的解决&quot;">​</a></h3><p>上边<code>A-&gt;B</code>数据传输应该没什么问题，主要是<code>A-&gt;C</code>数据传输，有以下几个问题：</p><p>（1）问题一：<code>A</code> 给 <code>C</code> 发数据包，怎么知道是否要通过路由器转发呢？</p><p>（2）问题二：大家都有<code>MAC</code>和<code>IP</code>，<code>A</code>怎么知道哪个是路由器的？</p><p>（3）问题三：路由器怎么知道<code>C</code>在哪？</p><p>（4）问题四：刚才说的都是 <code>IP</code> 层，但发送数据包的数据链路层需要知道 <code>MAC</code> 地址，可是只知道 <code>IP</code> 地址该怎么办呢？</p><h4 id="_4-1-问题一-子网和子网掩码" tabindex="-1">4.1 问题一：子网和子网掩码 <a class="header-anchor" href="#_4-1-问题一-子网和子网掩码" aria-label="Permalink to &quot;4.1 问题一：子网和子网掩码&quot;">​</a></h4><p>先来解决一下问题一：<code>A</code> 给 <code>C</code> 发数据包，怎么知道是否要通过路由器转发呢？</p><p>如果 <code>A</code> 向 <code>B</code> 发送数据，数据包可以直接经交换机转发给 <code>B</code>，不需要发送给路由器；如果 <code>A</code> 向 <code>C</code> 发送数据，<code>A</code> 必须先将数据包发送给路由器，再由路由器转发给 <code>C</code>。也就是说，不同的机器之间通信，有时需要将数据包发送给路由器，有时就不需要，那么机器是如何判别两种情况的呢?答案就是<strong>子网</strong>。</p><p>先深入了解一点<code>IP</code>地址的知识，就是<code>IP</code>地址其实是有两部分组成的：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">IP</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 地址</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 网络号</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 主机号</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>网络号和主机号一共是 <code>32</code> 位二进制数，它们各自占用的二进制位数并不固定。所谓子网，指的是一个局域网内所有 <code>IP</code> 网络号相同的机器组成的网络。</p><p>如果发送方<code>IP</code>与接收方<code>IP</code>处于同一个子网，就直接将数据包通过交换机发送出去，发送方<code>IP</code>与接收方<code>IP</code>不是在同一个子网中，就需要将数据包通过路由器转发出去。</p><ul><li><code>192.168.0.1</code> 和 <code>192.168.0.2</code> 的网络号都是<code>192.168.0</code>，所以<code>A</code>、<code>B</code>两台计算机处于同一个子网，所以它俩传输数据直接通过交换机就可以了；</li><li><code>192.168.0.1</code> 和 <code>192.168.1.1</code> 的网络号都是<code>192.168.1</code>，所以<code>C</code>、<code>D</code>两台计算机处于相同子网，但是它俩与<code>A</code>、<code>B</code>不在同一个子网，所以<code>A</code>与<code>C</code>之间就需要通过路由器转发一下数据包了。</li></ul><p>这是我们人为规定的，也就是说我们想表示，对于 <code>192.168.0.1</code> 来说：<code>192.168.0.xxx</code> 开头的，就算是在一个子网，否则就是在不同的子网。对于 <code>192.168.1.1</code>也是一样的。那么这只是我们自己这样理解，计算机不理解没用啊，计算机不理解就无法判断两个<code>IP</code>地址是否处于同一个子网。</p><p>于是就出现了<strong>子网掩码</strong> ，例如，上图中，我们将计算机的子网掩码定为 <code>255.255.255.0</code>这表示，将发送方 <code>IP</code> 与接收方 <code>IP</code> 分别同这个子网掩码进行<strong>与运算</strong>，若结果相等则是在一个子网，不相等就是在不同子网。比如</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">A计算机：</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.0.1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">255.255.255.0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.0.0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">B计算机：</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.0.2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">255.255.255.0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.0.0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">C计算机：</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.1.1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">255.255.255.0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.1.0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">D计算机：</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.1.2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">255.255.255.0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.1.0</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>这样便很容易得出，<code>A</code> 与 <code>B</code> 在同一个子网，<code>C</code> 与 <code>D</code> 在同一个子网，但是 <code>A</code> 与<code>C</code>就不在同一个子网，与 <code>D</code> 也不在同一个子网，如此这般，上边的图片就划分为了两个子网。</p><img src="`+C+'" alt="image-20220613154045980" style="zoom:50%;"><p>所以<code>A</code> 给 <code>C</code> 发数据包，先计算<code>A</code>和<code>C</code>是否在一个子网中，若在同一个子网，那么就不需要通过路由器转发，若不再在同一个子网，就需要通过路由器转发了。</p><p>所以如果 A 给 C 发消息，A 和 C 的 IP 地址分别 &amp; A 机器配置的子网掩码，发现不相等，则 A 认为 C 和自己不在同一个子网，于是把包发给路由器，就不管了，<strong>之后怎么转发，A 不关心</strong>。</p><h4 id="_4-2-问题二-默认网关" tabindex="-1">4.2 问题二：默认网关 <a class="header-anchor" href="#_4-2-问题二-默认网关" aria-label="Permalink to &quot;4.2 问题二：默认网关&quot;">​</a></h4><p>然后是问题二：大家都有<code>MAC</code>和<code>IP</code>，<code>A</code>怎么知道哪个是路由器的？</p><p>这个问题的答案是默认网关<code>Default Gateway</code>，也叫<strong>缺省网关</strong>。<code>A</code>发送数据到路由器这个说法其实并不准确，应该说<code>A</code>将数据包发给默认网关。</p><p>对 <code>A</code> 来说，<code>A</code> 只能<strong>直接</strong>把包发给同处于一个子网下的某个 <code>IP</code> 上，所以发给路由器还是发给某个计算机，对 <code>A</code> 来说也不关心，只要这个设备有个 <code>IP</code> 地址就行。所以其实<strong>默认网关，就是 A 在自己计算机里配置的一个 IP 地址</strong>，以便在发数据包给不同子网的机器时，可以先发给这个 <code>IP</code> 地址。</p><img src="'+F+'" alt="image-20220613162405651" style="zoom:50%;"><blockquote><p>这里我就有些迷了，我们听到过的概念有路由器，网关，默认网关，它们有什么关系？</p><ul><li><strong>网关</strong></li></ul><p>网关实质上是一个网络通向其他网络的<code>IP</code>地址，是自己出口的<code>IP</code>地址，也是别人入口的<code>IP</code>地址，就像一个出入的网络关口。它主要是用来连接两种不同的网络，同时，网关还能够同时与两边的主机之间进行通信，但是两边的主机是不能够直接进行通信，是必须要经过网关才能进行通信。<strong>网关的工作是在应用层当中的</strong>。网关它可以是路由器，交换机或者是PC。</p><ul><li><strong>默认网关</strong></li></ul><p>一台主机可以有多个网关。默认网关就是一台主机如果找不到可用的网关，就把数据包发给默认指定的网关，由这个网关来处理数据包。默认网关必须是计算机自己所在的网段（将<code>IP</code>地址和子网掩码作与运算，得到网段）中的<code>IP</code>地址，而不能填写其他网段中的<code>IP</code>地址。</p><ul><li><strong>路由器</strong></li></ul><p>路由器它是属于网络层设备，通常是以包为单位进行数据的发送。路由器它是一个<strong>网络层系统</strong>。我们在这个路由器的子接口处设置的<code>IP</code>地址就是网关。</p></blockquote><h4 id="_4-3-问题三-路由表" tabindex="-1">4.3 问题三：路由表 <a class="header-anchor" href="#_4-3-问题三-路由表" aria-label="Permalink to &quot;4.3 问题三：路由表&quot;">​</a></h4><p>接下来是问题三：路由器又是如何知道<code>C</code>在哪里的？</p><p>一台路由器有多个网口，每个网口都可以连接一个局域网。接收到数据包的路由器，必须先判定出目标机器所在局域网占用的网口号，才能将数据包转发出去。</p><p>和交换机类似，路由器的内部也维护着一张表格，记录着各个网络占用的网口号，通常称为<strong>路由表</strong>。路由器中的路由表是通过一些算法建立的，比如向量-距离算法、链路-状态算法等（没学过，不是很懂，不过问题不大，重点暂时不在这里）。不同于 <code>MAC</code> 地址表的是，路由表并不是一对一这种明确关系:</p><table><tbody><tr><td align="center">目的地址</td><td align="center">子网掩码</td><td align="center">下一跳</td><td align="center">端口</td></tr><tr><td align="left">192.168.0.0</td><td align="left">255.255.255.0</td><td align="center"></td><td align="center">0</td></tr><tr><td align="left">192.168.0.254</td><td align="left">255.255.255.255</td><td align="center"></td><td align="center">0</td></tr><tr><td align="left">192.168.1.0</td><td align="left">255.255.255.0</td><td align="center"></td><td align="center">1</td></tr><tr><td align="left">192.168.1.254</td><td align="left">255.255.255.255</td><td align="center"></td><td align="center">1</td></tr></tbody></table> 通过将目标地址和子网掩码做按位与运算，就可以判定目标机器所处的子网。所谓下一跳地址，当网络中有多个路由器相连时，数据包可能途径多个路由器，这时才会用到下一跳地址。 <p>先来看一下另一种IP地址的表示方式。对于<code>IP</code>地址的写法，还有一种，由于子网掩码其实就表示前多少位表示子网的网段，所以如 <code>192.168.0.0</code>（<code>255.255.255.0</code>） 也可以简写为 <code>192.168.0.0/24</code>，<code>/24</code>就指的是前 <code>24</code> 位二进制数为网络号，也就是<code>192.168.0</code>，所以路由表也可以像下边这样表示：</p><table><tbody><tr><td align="center">目的地址</td><td align="center">下一跳</td><td align="center">端口</td></tr><tr><td align="left">192.168.0.0/24</td><td align="center"></td><td align="center">0</td></tr><tr><td align="left">192.168.0.254/32</td><td align="center"></td><td align="center">0</td></tr><tr><td align="left">192.168.1.0/24</td><td align="center"></td><td align="center">1</td></tr><tr><td align="left">192.168.1.254/32</td><td align="center"></td><td align="center">1</td></tr></tbody></table> 通过下边这张表格，其实还要更好理解一些，路由表就表示，`192.168.0.xxx` 这个子网下的，都转发到 `0` 号端口，`192.168.1.xxx` 这个子网下的，都转发到 `1` 号端口。下一跳列还没有值，就先不用管了。 <img src="'+P+'" alt="img" style="zoom:95%;"><p>整个过程就是：</p><ul><li><code>A</code> 向<code>C</code>发送数据，借助子网掩码判断出它们处于不同的子网，因此 <code>A</code> 会将数据发送给默认网关，在这个图中也就是路由器。发送数据包之前，<code>A</code> 机器必须先通过 <code>ARP</code> 协议获得路由器的 <code>MAC</code> 地址并存入数据包中，才能将数据包发出；</li><li>数据包首先经过交换机 <code>1</code>，根据数据包中的目标 <code>MAC</code> 地址，在 <code>MAC</code> 地址表中查到路由器 <code>1</code> 占用的网口，将数据包从该网口转发给路由器；</li><li>接收到数据包的路由器会做两件事，首先是获取包中的目的 <code>IP</code> 地址，借助路由表查到计算机 <code>C</code> 所在局域网占用的是 <code>1</code> 号网口；然后再通过 <code>ARP</code> 协议获得 <code>C</code> 的 <code>MAC</code> 地址并作为目的 <code>MAC</code> 地址更新到数据包中，最后将数据包从 <code>1</code> 号网口发出；</li><li>交换机 <code>2</code> 接收到数据包后，根据数据包中的目的 <code>MAC</code> 地址，从 <code>MAC</code> 地址表查到 <code>C</code> 占用的网口号，于是从该网口将数据包发给 <code>C</code>；</li><li><code>C</code> 收到数据包后，发现此数据确实是发给自己的，于是收下了数据。</li></ul><h4 id="_4-4-问题四-arp" tabindex="-1">4.4 问题四：<code>ARP</code> <a class="header-anchor" href="#_4-4-问题四-arp" aria-label="Permalink to &quot;4.4 问题四：`ARP`&quot;">​</a></h4><p>最后一个问题：前边说的都是 <code>IP</code> 层，但发送数据包的数据链路层需要知道 <code>MAC</code> 地址，可是只知道 <code>IP</code> 地址，不知道<code>MAC</code>地址的话，该怎么办呢？</p><p>我们只知道<code>IP</code>地址，所以我们需要通过某种方式，由<code>IP</code>地址来找到对应的<code>MAC</code>地址。也就是通过某种方式，找到 <strong>192.168.0.2</strong> 对应的 MAC 地址 <strong>BBBB</strong>。这种方式就是<code>ARP</code>（<code>Address Resoloution Protocol</code>）全称<strong>地址解析协议</strong>，该协议就是专门根据目标机器的 <code>IP</code> 地址获取它的 <code>MAC</code> 地址。该种协议是怎么实现<code>IP</code>到<code>MAC</code>的获取的呢？跟前边一样，也是一张表。</p><p>同一局域网内的每台计算机（包括路由器）都维护着一张表格，用来记录其它机器 <code>IP</code> 地址和 <code>MAC</code> 地址的对应关系，通常称为 <code>arp</code> 表。</p><table><tbody><tr><td align="center">IP 地址</td><td align="center">MAC 地址</td></tr><tr><td align="center">192.168.0.2</td><td align="center">BBBB</td></tr></tbody></table><p>一开始的时候这个<code>arp</code>表是<strong>空的</strong>，计算机<code>A</code> 为了知道 <code>B</code>（<code>192.168.0.2</code>）的 <code>MAC</code> 地址，将会<strong>广播</strong>一条 <code>arp</code> 请求，<code>B</code> 收到请求后，带上自己的 <code>MAC</code> 地址给 <code>A</code> 一个<strong>响应</strong>。此时 <code>A</code> 便更新了自己的 <code>arp</code> 表。这样通过大家不断广播 <code>arp</code> 请求，最终所有计算机里面都会将 <code>arp</code> 缓存表更新完整。</p><h2 id="五、一个通信实例" tabindex="-1">五、一个通信实例 <a class="header-anchor" href="#五、一个通信实例" aria-label="Permalink to &quot;五、一个通信实例&quot;">​</a></h2><h3 id="_1-下一跳地址" tabindex="-1">1. 下一跳地址 <a class="header-anchor" href="#_1-下一跳地址" aria-label="Permalink to &quot;1. 下一跳地址&quot;">​</a></h3><p>如下图所示的网络拓扑图：</p><img src="'+y+'" alt="img" style="zoom:80%;"><p>图中有两个路由器连接，现在假设<code>A</code>要向<code>F</code>发送数据，数据包要途径两个路由器后才能到达 <code>F</code>，这种情况下就需要用到路由表中的下一跳地址。路由器 <code>1</code> 连接了路由器 <code>2</code>，所以路由器<code>1</code>的路由表有了下一跳地址这一个概念，所以它的路由表就变成了这个样子。</p><table tabindex="0"><thead><tr><th>子网</th><th>下一跳地址</th><th>端口</th></tr></thead><tbody><tr><td>192.168.0.0/24</td><td></td><td>1</td></tr><tr><td>192.168.0.254/32</td><td></td><td>1</td></tr><tr><td>192.168.1.0/24</td><td></td><td>2</td></tr><tr><td>192.168.1.254/32</td><td></td><td>2</td></tr><tr><td>192.168.2.0/24</td><td>192.168.100.5</td><td></td></tr><tr><td>192.168.100.0/24</td><td></td><td>3</td></tr><tr><td>192.168.100.4/32</td><td></td><td>3</td></tr></tbody></table><p>如果匹配到了有下一跳地址的一项，则需要再次匹配，找到其端口，并找到下一跳 <code>IP</code> 的 <code>MAC</code> 地址。也就是说找来找去，最终必须能映射到一个端口号，然后从这个端口号把数据包发出去。</p><h3 id="_2-通信过程分析" tabindex="-1">2. 通信过程分析 <a class="header-anchor" href="#_2-通信过程分析" aria-label="Permalink to &quot;2. 通信过程分析&quot;">​</a></h3><img src="'+f+'" alt="img"><ul><li><code>A</code>到路由器<code>1</code></li></ul><p>（1）<code>A</code> 的 <code>IP</code> 地址为 <code>192.168.0.1</code>，<code>F</code> 的 <code>IP</code> 地址为 <code>192.168.2.2</code>。 <code>A</code> 的子网掩码为 <code>255.255.255.0</code>，分别和两个 <code>IP</code> 地址做按位与运算，计算出的结果不同，说明 <code>A</code> 和 <code>F</code> 位于不同的子网。所以<code>A</code>决定将数据包转发给默认网关（<code>192.168.0.254</code>），在这里也就是路由器 <code>1</code>。</p><p>（2）<code>A</code> 通过 <code>ARP</code> 找到默认网关 <code>192.168.0.254</code> 的 <code>MAC</code> 地址。</p><p>（3）<code>A</code> 将源 <code>MAC</code> 地址（<code>AAAA</code>）与网关 <code>MAC</code> 地址（<code>ABAB</code>）封装在数据链路层头部，又将源 <code>IP</code> 地址（<code>192.168.0.1</code>）和目的 <code>IP</code> 地址（<code>192.168.2.2</code>）（注意这里千万不要以为填写的是默认网关的 <code>IP</code> 地址，从始至终这个数据包的两个 <code>IP</code> 地址都是不变的，只有 <code>MAC</code> 地址在不断变化）封装在网络层头部，然后发出数据包，数据包的格式如下：</p><img src="'+v+'" alt="image-20220613202143988" style="zoom:50%;"><p>（4）数据包会途径交换机 <code>1</code>，借助交换机内部的 <code>MAC</code> 地址表，可以查到路由器 <code>1</code> 占用着交换机的 <code>3</code> 号网口，交换机 <code>1</code> 会将数据包从 <code>3</code> 号网口转发给路由器 <code>1</code>。</p><ul><li>路由器<code>1</code>到路由器<code>2</code></li></ul><p>（5） 数据包来到了路由器 <code>1</code>，路由器<code>1</code>从路由表中查找到目标 <code>IP</code> （<code>192.168.2.2</code>）对应的下一跳地址为 <code>192.168.100.5</code>。这种情况下，路由器 <code>1</code> 会做两件事：一是再次去路由表中查找 <code>192.168.100.5</code> 所在子网对应的网口号，结果为 <code>3</code> 号；二是借助 <code>ARP</code> 协议查找 <code>192.168.100.5</code> 对应的 <code>MAC</code> 地址，也就是路由器 <code>2</code> 的 <code>MAC</code> 地址 <code>D2D2</code>，然后更新数据包，如下图所示：</p><img src="'+E+'" alt="image-20220613202749784" style="zoom:50%;"><p>（6）更新后的数据包会被路由器<code>1</code>从 <code>3</code> 号网口转发给路由器 <code>2</code>。</p><ul><li>路由器<code>2</code>到<code>F</code></li></ul><p>（7）数据包来到了路由器 <code>2</code>，路由器<code>2</code>从路由表查找目标 <code>IP</code>（<code>192.168.2.2</code>） 所在子网占用的网口号（假设为 <code>1</code> 号网口）。此时路由器 <code>2</code> 需要知道 <code>192.168.2.2</code> 的 <code>MAC</code> 地址了，于是借助 <code>ARP</code> 协议找到 <code>192.168.2.2</code> 对应的 <code>MAC</code> 地址是 <code>FFFF</code>，然后更新数据包，如下图所示：</p><img src="'+M+'" alt="image-20220613203221165" style="zoom:50%;"><p>（8）更新后的数据包会被路由器 <code>2</code> 从 <code>1</code> 号网口转发给交换机<code>3</code>。</p><p>（9）交换机<code>3</code>收到了数据包，发现目的 <code>MAC</code> 地址为 <code>FFFF</code>，查询其 <code>MAC</code> 地址表，发现应该从其 <code>6</code> 号网口出去，于是从 <code>6</code> 号网口把数据包发出去。</p><ul><li>完成<code>A</code>→<code>F</code>的数据传输</li></ul><p>（10） <code>F</code> 最终收到了数据包，并且发现目的 <code>MAC</code> 地址就是自己，于是收下了这个包。</p><h2 id="六、端口和端口号" tabindex="-1">六、端口和端口号 <a class="header-anchor" href="#六、端口和端口号" aria-label="Permalink to &quot;六、端口和端口号&quot;">​</a></h2><p>现在可以想一个问题，就是我们会在电脑上运行QQ、微信、钉钉、网页浏览器等 ，这些进程都需要进行网络连接，它们都可通过网络发送/接收数据，那么这里就有一个问题？主机接收到网络数据之后，如何确定该数据是哪个进程对应的接收数据呢？</p><h3 id="_1-什么是端口号" tabindex="-1">1. 什么是端口号 <a class="header-anchor" href="#_1-什么是端口号" aria-label="Permalink to &quot;1. 什么是端口号&quot;">​</a></h3><p>在前边，我们已经了解了<code>IP</code>地址，<code>MAC</code>地址，有了这两个，我们就可以找到目标计算机，但是呢其实仍然不能进行通信。一台计算机可以同时提供多种网络服务，例如 <code>Web</code> 服务（网站）、<code>FTP</code> 服务（文件传输服务）、<code>SMTP</code> 服务（邮箱服务）等，仅有<code>IP</code>地址和<code>MAC</code>地址的话，计算机虽然<strong>可以正确接收到数据包</strong>，但是却<strong>不知道要将数据包交给哪个网络程序来处理</strong>，这个时候通信还是就会失败。</p><p>一台拥有<code>IP</code>地址的主机可以提供许多服务，比如上面说的<code>Web</code>服务、<code>FTP</code>服务、<code>SMTP</code>服务等，这些服务都是能够进行网络通信的进程，<code>IP</code>地址只能区分网络中不同的主机，并不能区分主机中的这些进程，而一台主机通常只有一个<code>IP</code>地址，所以不能只靠<code>IP</code>地址。</p><p>在这个时候，计算机会为每个网络程序分配一个独一无二的<strong>端口号</strong>（<code>Port Number</code>），例如，<code>Web</code> 服务的端口号是 <code>80</code>，<code>FTP</code> 服务的端口号是 <code>21</code>，<code>SMTP</code> 服务的端口号是 <code>25</code>。所谓<strong>端口</strong>（<code>Port</code>）其实是一个虚拟的、逻辑上的概念。我们可以将端口理解为一道门，数据通过这道门流入流出，每道门有不同的编号，就是端口号，门的后边就是一个小房间，房间里就是一种网络服务。于是，我们现在就可以通过 <code>IP</code>地址<code>+</code>端口号 来区分主机不同的进程了。需要注意的是，前边的说交换机和路由器的时候，虽然没有提及端口，但传输的数据包中也会还是会记录通信双方的端口号，最终用<strong>端口号来确定将数据包发送给机器里的哪个网络程序</strong>。</p><img src="'+x+'" alt="image-20220614053923911" style="zoom:50%;"><p>端口号一般由<code>IANA</code> (<code>Internet Assigned Numbers Authority</code>) 管理。<code>TCP/IP</code>协议中的服务端口，通过不同的逻辑端口来区分不同的服务。一个<code>IP</code>地址的端口通过<code>16 bit</code>（比特）进行编号，最多可以有<code>65536</code>个端口。端口是通过端口号来标记的，端口号本质上就是一个数字编号，用来在一台主机中唯一标识一个能上网（能够进行网络通信） 的进程， 端口号只有整数，范围是从<code>0</code> 到<code>65535</code>。</p><h3 id="_2-端口号分类" tabindex="-1">2. 端口号分类 <a class="header-anchor" href="#_2-端口号分类" aria-label="Permalink to &quot;2. 端口号分类&quot;">​</a></h3><p>端口号一般有以下几类：</p><table><tbody><tr><td align="center" width="150px">公认端口</td><td align="left">1~1023（1~255之间为众所周知端口，256~1023端口通常由UNIX系统占用）</td></tr><tr><td align="center" width="150px">注册端口</td><td align="left">1024~49150</td></tr><tr><td align="center" width="150px">动态或私有端口</td><td align="left">49151~65535</td></tr></tbody></table> 【注意】我们写程序的时候分配端口号不建议使用`1024~5000`，但是我们可以放心使用`5001~65535`。 <h3 id="_3-常用端口号" tabindex="-1">3. 常用端口号 <a class="header-anchor" href="#_3-常用端口号" aria-label="Permalink to &quot;3. 常用端口号&quot;">​</a></h3><p>常用端口号汇总：</p><table><tbody><tr><td align="center" width="160px">服务</td><td align="center" width="150px"> 端口号</td><td align="left"> 说明</td></tr><tr><td align="center" width="160px" rowspan="2">FTP</td><td align="center" width="150px"> 20</td><td align="left">文件传输协议，FTP服务器真正传输所用的端口，用于上传、下载</td></tr><tr><td align="center" width="150px"> 21</td><td align="left">文件传输协议，用于FTP的登陆认证 </td></tr><tr><td align="center" width="160px">SSH、SFTP</td><td align="center" width="150px"> 22</td><td align="left"> 加密的远程登录，文件传输<br>SSH：安全外壳协议，专为远程登录会话和其他网络服务提供安全性的协议</td></tr><tr><td align="center" width="160px">Telnet</td><td align="center" width="150px"> 23</td><td align="left"> 终端远程登录协议（在本地主机上使用此端口与远程服务器的22/3389端口连接），它为用户提供了在本地计算机上完成远程主机工作的能力。</td></tr><tr><td align="center" width="160px">SMTP</td><td align="center" width="150px"> 25</td><td align="left">简单邮件传输协议，它帮助每台计算机在发送或中转信件时找到下一个目的地。</td></tr><tr><td align="center" width="160px">TFTP</td><td align="center" width="150px"> 69</td><td align="left">简单文件传输协议，主机之间进行简单文件传输</td></tr><tr><td align="center" width="160px">HTTP</td><td align="center" width="150px"> 80</td><td align="left">超文本传输协议，用于网页浏览</td></tr><tr><td align="center" width="160px">POP3</td><td align="center" width="150px"> 110</td><td align="left"> 邮局协议版本3，本协议主要用于支持使用客户端远程管理在服务器上的电子邮件</td></tr><tr><td align="center" width="160px">SMTP</td><td align="center" width="150px"> 161</td><td align="left"> Simple Network Management Protocol，简单网络管理协议</td></tr><tr><td align="center" width="160px">SNMP Trap</td><td align="center" width="150px"> 162</td><td align="left"> SNMP陷阱</td></tr><tr><td align="center" width="160px">HTTPS</td><td align="center" width="150px"> 443</td><td align="left"> 加密的网页浏览端口</td></tr><tr><td align="center" width="160px">CIFS</td><td align="center" width="150px"> 445</td><td align="left"> 公共Internet文件系统</td></tr><tr><td align="center" width="160px">sql server</td><td align="center" width="150px"> 1433</td><td align="left"> Microsoft的SQL服务开放的端口</td></tr><tr><td align="center" width="160px">Oracle</td><td align="center" width="150px"> 1521</td><td align="left"> Oracle数据库的默认监听端口</td></tr><tr><td align="center" width="160px">NFS</td><td align="center" width="150px"> 2049</td><td align="left"> 通过网络，让不同的机器、不同的操作系统实现文件共享</td></tr><tr><td align="center" width="160px">MySQL</td><td align="center" width="150px"> 3306</td><td align="left"> mysql 数据库的默认端口</td></tr><tr><td align="center" width="160px">WIN2003远程登录</td><td align="center" width="150px"> 3389</td><td align="left"> Windows 2000(2003) Server远程桌面的服务端口，本地服务器开放此端口，去连接到远程的服务器</td></tr><tr><td align="center" width="160px">QQ</td><td align="center" width="150px"> 4000</td><td align="left"> 腾讯QQ客户端开放此端口</td></tr><tr><td align="center" width="160px">WebLogic</td><td align="center" width="150px"> 7001</td><td align="left"> 一个基于JAVAEE架构的中间件，WebLogic是用于开发、集成、部署和管理大型分布式Web应用、网络应用和数据库应用的Java应用服务器</td></tr><tr><td align="center" width="160px">Wingate</td><td align="center" width="150px"> 8010</td><td align="left"> Wingate代理开放此端口</td></tr><tr><td align="center" width="160px">TOMCAT</td><td align="center" width="150px"> 8080</td><td align="left"> WWW代理开放此端口</td></tr></tbody></table> ## 七、字节序 <h3 id="_1-两种字节序" tabindex="-1">1. 两种字节序 <a class="header-anchor" href="#_1-两种字节序" aria-label="Permalink to &quot;1. 两种字节序&quot;">​</a></h3><p>还记得学习<code>C</code>语言的时候，我们有接触到过大端模式和小端模式，我们知道<code>CPU</code>向内存保存数据的方式有两种：</p><ul><li>大端序（<code>Big Endian</code>）：高位字节存放到低位地址（高位字节在前）。</li><li>小端序（<code>Little Endian</code>）：高位字节存放到高位地址（低位字节在前）。</li></ul><p>而<strong>网络中传输的数据必须按网络字节序，即大端字节序</strong>，为了避免不同类别主机之间在数据交换时由于对于字节序的不同而导致的差错，引入了<strong>网络字节序</strong>(<code>NBO，Network Byte Order</code>)的概念，在本地主机中由<code>CPU</code>保存的字节序被称为<strong>主机字节序</strong>(<code>HBO，Host Byte Order</code>)。</p><ul><li><p>不同的机器<code>HBO</code>是不一样的，这与<code>CPU</code>的设计有关。</p></li><li><p><code>Motorola 68K</code>系列、<code>ARM</code>系列，<code>HBO</code>与<code>NBO</code>是一致的。</p></li><li><p><code>Intel X86</code>系列，<code>HBO</code>与<code>NBO</code>不一致。</p></li></ul><h3 id="_2-字节序转换" tabindex="-1">2. 字节序转换 <a class="header-anchor" href="#_2-字节序转换" aria-label="Permalink to &quot;2. 字节序转换&quot;">​</a></h3><p>小端序系统和大端序系统通信时会发生数据解析错误。因此在发送数据前，要将数据转换为统一的格式——网络字节序。在<code>C</code>语言编程中，有以下函数可以帮助我们完成转换。</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">u_short</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> htons</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">u_short</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> short</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  /* host to network short，将short类型数据从主机字节序转换为网络字节序。*/</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">u_long</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> htonl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">u_long</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> hostlong</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> /* host to network long，将long类型数据从主机字节序转换为网络字节序。*/</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">u_long</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ntohl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">u_long</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> hostlong</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> /* network to host long，将long类型数据从网络字节序转换为主机字节序。*/</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">u_short</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ntohs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">u_short</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> short</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  /* network to host short，将short类型数据从网络字节序转换为主机字节序。*/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>【说明】后边学习<code>Socket</code>编程的时候会详细学习这几个函数（数据类型定义可能略有不同，但是使用方法完全一致）。</p><h2 id="八、总结" tabindex="-1">八、总结 <a class="header-anchor" href="#八、总结" aria-label="Permalink to &quot;八、总结&quot;">​</a></h2><p>本文分别从网线直连（包括集线器）、交换机和路由器的角度讲解了数据在网络中的传输细节，下边做一个总结吧。</p><h3 id="_1-计算机" tabindex="-1">1. 计算机 <a class="header-anchor" href="#_1-计算机" aria-label="Permalink to &quot;1. 计算机&quot;">​</a></h3><p>（1）首先知道自己的<code>IP</code>和目标计算机的 <code>IP</code> 地址。当通信双方位于不同的局域网时，需要借助第三方服务器得知对方默认网关的 <code>IP</code> 地址；</p><p>（2）通过子网掩码，判定是否和目标<code>IP</code>处于同一个子网：</p><ul><li>若同处一个子网，通过 <code>ARP</code> 协议直接获得对方的 <code>MAC</code> 地址，数据包通过交换机转发给目标计算机；</li><li>若位于不同的子网，通过 <code>ARP</code> 协议获得当前局域网中默认网关的 <code>MAC</code> 地址，数据包通过默认网关的<code>MAC</code>地址转发出去。</li></ul><h3 id="_2-交换机" tabindex="-1">2. 交换机 <a class="header-anchor" href="#_2-交换机" aria-label="Permalink to &quot;2. 交换机&quot;">​</a></h3><p>（1）接收到的数据包必须包含目标计算机的 <code>MAC</code> 地址；</p><p>（2）在<code>MAC</code> 地址表中查询目标计算机占用的网口号，若查询成功，直接将数据包通过指定网口发送给目标机器；若查询失败，将数据包从所有网口发送出去。</p><h3 id="_3-路由器" tabindex="-1">3. 路由器 <a class="header-anchor" href="#_3-路由器" aria-label="Permalink to &quot;3. 路由器&quot;">​</a></h3><p>（1）接收到的数据包必须包含目标计算机的 <code>IP</code> 地址；</p><p>（2）通过路由表中记录的信息，若找到目标计算机所在子网占用的网口号，将数据包通过该网口转发出去，若找到目标机器 <code>IP</code> 地址对应的下一跳地址，将数据包转发到下一个路由器。若是什么也查不到，那就返回一个路由不可达的数据包。</p><h3 id="_4-三张表" tabindex="-1">4. 三张表 <a class="header-anchor" href="#_4-三张表" aria-label="Permalink to &quot;4. 三张表&quot;">​</a></h3><h4 id="_4-1-是什么" tabindex="-1">4.1 是什么？ <a class="header-anchor" href="#_4-1-是什么" aria-label="Permalink to &quot;4.1 是什么？&quot;">​</a></h4><ul><li>交换机中有 <code>MAC</code> 地址表用于映射 <code>MAC</code> 地址和它的网口。</li><li>路由器中有路由表用于映射<code>IP</code> 地址(段)和它的网口。</li><li>计算机和路由器中都有 <code>arp</code> 缓存表用于缓存 <code>IP</code> 和 <code>MAC</code> 地址的映射关系。</li></ul><h4 id="_4-2怎么来的" tabindex="-1">4.2怎么来的？ <a class="header-anchor" href="#_4-2怎么来的" aria-label="Permalink to &quot;4.2怎么来的？&quot;">​</a></h4><ul><li><code>MAC</code> 地址表是通过以太网内各节点之间不断通过交换机通信，不断完善起来的。</li><li>路由表是各种路由算法 <code>+</code> 人工配置逐步完善起来的。</li><li><code>arp</code> 缓存表是不断通过 <code>arp</code> 协议的请求逐步完善起来的。</li></ul><blockquote><p>参考资料：</p><p><a href="https://mp.weixin.qq.com/s?__biz=MzkxMDc1MDg1Nw==&amp;mid=2247508504&amp;idx=1&amp;sn=b21196cfd1c3cbde80119240c9d2cd81&amp;source=41#wechat_redirect" target="_blank" rel="noreferrer">如果让你来设计网络 (qq.com)</a></p><p><a href="https://www.yuque.com/jiexuewu/hlsxub/sxo9ik?singleDoc#" target="_blank" rel="noreferrer">网络通信简明教程 (yuque.com)</a></p></blockquote>',201)])])}const Y=d(B,[["render",q]]);export{T as __pageData,Y as default};
